import json, requests, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026年6月30日"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**巡检时间：** 2026年6月30日 15:07 (AEST)\n\n---\n\n**今日 5 品牌均无新品上架或状态变更。**\n\n📊 **各品牌概况：**\n\n- **海信 Hisense** — 53款产品，品类/型号与基线一致，无变化\n- **美的 Midea** — 15款产品，MDRS925FIM45AP/MDRF923FIM45AP 仍为 Coming Soon，无新增\n- **三星 Samsung** — 官网动态加载，搜索未发现 2026 年新冰箱型号\n- **LG** — 官网反爬保护，搜索未发现 2026 年澳洲新冰箱型号\n- **西屋 Westinghouse** — 75款产品，无变化\n\n---\n\n**近期关键变化回顾：**\n- 6/30 上午：MDRT580MTF45AP (413L Top Mount) Coming Soon → 可购买\n- 6/29：MDRF632FGD46APW (474L Quad Door) Coming Soon → 可购买"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=10)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print(json.dumps(result, ensure_ascii=False, indent=2))

